package cn.nankexi;

import java.util.*;
import java.lang.reflect.*;
import org.bukkit.*;
import org.bukkit.entity.Player;
import org.bukkit.configuration.file.YamlConfiguration;
import org.bukkit.generator.*;
import org.bukkit.event.player.*;
import org.bukkit.plugin.java.JavaPlugin;
import net.milkbowl.vault.economy.*;

final class MiningFamilySmoke {
    static void run(JavaPlugin test,MiaoServer plugin)throws Exception{
        var mining=plugin.mining;var ledger=(YamlConfiguration)CommunitySmoke.get(mining,"ledger");var pending=(Map<?,?>)CommunitySmoke.get(mining,"pending");
        World main=Bukkit.getWorld("world"),mine=Bukkit.getWorld(NamespacedKey.minecraft("mining")),nether=Bukkit.getWorld(NamespacedKey.minecraft("mining_nether")),end=Bukkit.getWorld(NamespacedKey.minecraft("mining_the_end"));
        var groups=org.mvplugins.multiverse.inventories.MultiverseInventoriesApi.get().getWorldGroupManager();var survival=groups.getGroup("survival");
        for(World world:List.of(mine,nether,end)){CommunitySmoke.ok(MiningWorld.mine(world)&&world.getDifficulty()==Difficulty.PEACEFUL&&Boolean.TRUE.equals(world.getGameRuleValue(GameRule.KEEP_INVENTORY)),"all resource dimensions peaceful with inventory retained");CommunitySmoke.ok(groups.getGroupsForWorld(world.getName()).equals(List.of(survival)),"all resource dimensions share only survival inventory");CommunitySmoke.ok(RespawnSafety.safe(world.getSpawnLocation()),"each mining dimension has safe public entry");}
        oreCheck(test,plugin,mine);oreCheck(test,plugin,nether);
        var visitor=new CommunitySmoke.Fixture(test,"MiningFamilyVisitor",main);Map<UUID,Double> coins=new HashMap<>();coins.put(visitor.id,1000.0);int[] debits={0};
        Economy economy=(Economy)Proxy.newProxyInstance(test.getClass().getClassLoader(),new Class[]{Economy.class},(o,m,a)->{
            if(m.getName().equals("equals"))return o==a[0];if(m.getName().equals("hashCode"))return System.identityHashCode(o);
            if(Set.of("withdrawPlayer","depositPlayer").contains(m.getName())){UUID id=((OfflinePlayer)a[0]).getUniqueId();double amount=(double)a[1],balance=coins.getOrDefault(id,0.0);boolean debit=m.getName().equals("withdrawPlayer"),ok=!debit||balance>=amount;if(ok)coins.put(id,balance+(debit?-amount:amount));if(debit)debits[0]++;return new EconomyResponse(amount,coins.getOrDefault(id,0.0),ok?EconomyResponse.ResponseType.SUCCESS:EconomyResponse.ResponseType.FAILURE,"fixture");}Class<?> c=m.getReturnType();return c==boolean.class?true:c==double.class?0.0:c==String.class?"FamilyFixture":null;
        });Bukkit.getServicesManager().register(Economy.class,economy,test,org.bukkit.plugin.ServicePriority.Highest);
        try{
            var entry=new PlayerTeleportEvent(visitor.player,main.getSpawnLocation(),nether.getSpawnLocation(),PlayerTeleportEvent.TeleportCause.PLUGIN);mining.teleport(entry);CommunitySmoke.ok(!entry.isCancelled()&&coins.get(visitor.id)==800&&debits[0]==1,"direct mining Nether entry pays exactly 200");visitor.world=nether;mining.changed(new PlayerChangedWorldEvent(visitor.player,main));
            for(World destination:List.of(end,mine,nether)){var transfer=new PlayerTeleportEvent(visitor.player,visitor.world.getSpawnLocation(),destination.getSpawnLocation());mining.teleport(transfer);CommunitySmoke.ok(!transfer.isCancelled(),"valid family ticket permits dimension transfer");World from=visitor.world;visitor.world=destination;mining.changed(new PlayerChangedWorldEvent(visitor.player,from));}CommunitySmoke.ok(coins.get(visitor.id)==800&&debits[0]==1,"three dimensions use one ticket without reset visit counters");
            CommunitySmoke.ok(mining.reserve(visitor.id,Material.QUARTZ,8)==2&&mining.reserve(visitor.id,Material.GOLD_NUGGET,8)==2&&mining.reserve(visitor.id,Material.ANCIENT_DEBRIS,8)==2,"Nether resources participate in one-third withholding");
            visitor.world=end;var death=new PlayerRespawnEvent(visitor.player,end.getSpawnLocation(),false,false,false,PlayerRespawnEvent.RespawnReason.DEATH);plugin.respawnInDeathWorld(death);CommunitySmoke.ok(death.getRespawnLocation().getWorld()==main,"resource End death returns to survival overworld");var portal=new PlayerRespawnEvent(visitor.player,main.getSpawnLocation(),false,false,false,PlayerRespawnEvent.RespawnReason.END_PORTAL);plugin.respawnInDeathWorld(portal);CommunitySmoke.ok(portal.getRespawnLocation().getWorld()==mine,"resource End exit remains in resource family");
            visitor.world=main;mining.changed(new PlayerChangedWorldEvent(visitor.player,end));CommunitySmoke.ok(!ledger.getBoolean("players."+visitor.id+".active"),"leaving any resource dimension closes visit");
            test.getLogger().info("MINING_FAMILY_SMOKE_PASS: three peaceful shared-inventory dimensions, safe entries, one 200-coin ticket, Nether mineral tax, death and End-exit routing");
        }finally{pending.remove(visitor.id);ledger.set("players."+visitor.id,null);((fr.xephi.authme.data.auth.PlayerCache)CommunitySmoke.get(fr.xephi.authme.api.v3.AuthMeApi.getInstance(),"playerCache")).removePlayer(visitor.name.toLowerCase());Bukkit.getServicesManager().unregister(economy);}
        Map<String,UUID> keep=new HashMap<>(),old=new HashMap<>();for(String name:List.of("world","world_nether","world_the_end","flat","architect","lobby"))keep.put(name,Bukkit.getWorld(name).getUID());for(String name:MiningDimensions.NAMES)old.put(name,Bukkit.getWorld(NamespacedKey.minecraft(name)).getUID());long oldSeed=mine.getSeed(),schedule=ledger.getLong("next-reset");
        mining.reset();World fresh=Bukkit.getWorld(NamespacedKey.minecraft("mining"));CommunitySmoke.ok(!ledger.getBoolean("reset-in-progress")&&fresh!=null&&fresh.getSeed()!=oldSeed,"resource reset completes with new seed");
        for(String name:MiningDimensions.NAMES){World world=Bukkit.getWorld(NamespacedKey.minecraft(name));CommunitySmoke.ok(!world.getUID().equals(old.get(name))&&world.getSeed()==fresh.getSeed()&&world.getDifficulty()==Difficulty.PEACEFUL,"entire resource family regenerated together");}for(var world:keep.entrySet())CommunitySmoke.ok(Bukkit.getWorld(world.getKey()).getUID().equals(world.getValue()),"permanent dimensions preserved");ledger.set("next-reset",schedule);Field dirty=mining.getClass().getDeclaredField("dirty");dirty.setAccessible(true);dirty.setBoolean(mining,true);Method save=mining.getClass().getDeclaredMethod("save");save.setAccessible(true);save.invoke(mining);
        test.getLogger().info("MINING_FAMILY_RESET_SMOKE_PASS: all three UUIDs and seed refreshed together; survival/building/lobby identities unchanged");
    }
    static void oreCheck(JavaPlugin test,MiaoServer plugin,World world)throws Exception{
        BlockPopulator populator=(BlockPopulator)CommunitySmoke.get(plugin.mining,"populator");int min=world.getMinHeight(),max=world.getMaxHeight();boolean nether=world.getEnvironment()==World.Environment.NETHER;Map<Integer,Material> terrain=new HashMap<>();int air=(24<<8),chest=(24<<8)|16;terrain.put(air,Material.AIR);terrain.put(chest,Material.CHEST);
        LimitedRegion region=(LimitedRegion)Proxy.newProxyInstance(test.getClass().getClassLoader(),new Class[]{LimitedRegion.class},(o,m,a)->{if(m.getName().equals("getType")||m.getName().equals("setType")){int x=(int)a[0],y=(int)a[1],z=(int)a[2],pos=((y-min)<<8)|(x<<4)|z;if(m.getName().equals("getType"))return terrain.getOrDefault(pos,nether?Material.NETHERRACK:y<0?Material.DEEPSLATE:Material.STONE);terrain.put(pos,(Material)a[3]);return null;}Class<?> c=m.getReturnType();return c==boolean.class?true:c==int.class?0:null;});
        Method populate=populator.getClass().getDeclaredMethod("populate",WorldInfo.class,Random.class,int.class,int.class,LimitedRegion.class);populate.setAccessible(true);populate.invoke(populator,world,new Random(4926),0,0,region);
        Map<Integer,Material> ores=new HashMap<>();terrain.forEach((pos,material)->{if(MiningWorld.ORES.contains(material))ores.put(pos,material);});long eligible=256L*(max-min-2)-2;CommunitySmoke.ok(ores.size()==Math.round(eligible*.3)&&terrain.get(air)==Material.AIR&&terrain.get(chest)==Material.CHEST,"exact thirty percent coverage; no air or constructed blocks overwritten");
        int connected=0;for(var entry:ores.entrySet()){int pos=entry.getKey(),x=(pos>>4)&15,z=pos&15;String ore=entry.getValue().name().replace("DEEPSLATE_","");List<Integer> neighbors=new ArrayList<>(List.of(pos-256,pos+256));if(x>0)neighbors.add(pos-16);if(x<15)neighbors.add(pos+16);if(z>0)neighbors.add(pos-1);if(z<15)neighbors.add(pos+1);if(neighbors.stream().map(ores::get).filter(Objects::nonNull).anyMatch(m->m.name().replace("DEEPSLATE_","").equals(ore)))connected++;}
        CommunitySmoke.ok(connected>ores.size()*.95,"over ninety-five percent of ore has same-mineral face-adjacent neighbor");if(nether){long ancient=ores.values().stream().filter(m->m==Material.ANCIENT_DEBRIS).count();CommunitySmoke.ok(ancient<ores.size()*.003&&ores.containsValue(Material.NETHER_QUARTZ_ORE)&&ores.containsValue(Material.NETHER_GOLD_ORE),"Nether veins dominated by quartz/gold; ancient debris remains rare");}else{long common=ores.values().stream().filter(m->m.name().contains("COAL_ORE")||m.name().contains("IRON_ORE")||m.name().contains("COPPER_ORE")).count(),rare=ores.values().stream().filter(m->m.name().contains("DIAMOND_ORE")||m.name().contains("EMERALD_ORE")).count();CommunitySmoke.ok(common>ores.size()*.7&&rare<ores.size()*.04,"common minerals dominate; rare ores remain bounded");}
        test.getLogger().info("ORE_VEIN_SMOKE_PASS: "+world.getName()+" coverage="+ores.size()+", connected="+connected);
    }
}
